package com.pillar; import com.fasterxml.jackson.databind.*; import com.pillar.resources.Resource; import java.net.*; import java.net.http.*; import java.time.*; import java.util.*;
public class PillarClient { private final String apiKey, apiBase, apiVersion; private final HttpClient http; private final ObjectMapper json=new ObjectMapper(); public final Resource accounts, assets, balances, holdings, issueIntents, redeemIntents, transferIntents, holds, operations, events, webhookEndpoints, apiKeys; public record RequestOptions(String idempotencyKey, Duration timeout) {}
private PillarClient(Builder b){apiKey=b.apiKey;apiBase=b.apiBase;apiVersion=b.apiVersion;http=b.http; accounts=r("accounts");assets=r("assets");balances=r("balances");holdings=r("holdings");issueIntents=r("issue_intents");redeemIntents=r("redeem_intents");transferIntents=r("transfer_intents");holds=r("holds");operations=r("operations");events=r("events");webhookEndpoints=r("webhook_endpoints");apiKeys=r("api_keys");}
private Resource r(String p){return new Resource(this,"/v1/"+p);} public static Builder builder(String apiKey){return new Builder(apiKey);} public static class Builder{String apiKey, apiBase="https://api.pillar.local", apiVersion="2026-05-26"; HttpClient http=HttpClient.newHttpClient(); Builder(String k){apiKey=k;} public Builder apiBase(String v){apiBase=v;return this;} public Builder apiVersion(String v){apiVersion=v;return this;} public PillarClient build(){return new PillarClient(this);} }
public Map request(String method,String path,Map body,RequestOptions opts){ try{ var builder=HttpRequest.newBuilder(URI.create(apiBase+path)).header("Authorization","Bearer "+apiKey).header("Pillar-Version",apiVersion); if(opts!=null&&opts.idempotencyKey()!=null) builder.header("Idempotency-Key",opts.idempotencyKey()); if(body!=null) builder.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))); else builder.method(method,HttpRequest.BodyPublishers.noBody()); var res=http.send(builder.build(), HttpResponse.BodyHandlers.ofString()); if(res.statusCode()>=400) throw new PillarException(res.body(), res.statusCode(), res.headers().firstValue("request-id").orElse(null)); return res.body().isBlank()?new HashMap<>():json.readValue(res.body(), Map.class);}catch(Exception e){ if(e instanceof PillarException pe) throw pe; throw new PillarException(e.getMessage(),0,null);} }}
